def Nd(x): return 0.5*(1+math.erf(x/math.sqrt(2)))
def prem(s): return 2*(Nd(s/2)-Nd(-s/2))
def run(R,label,W=3,IVM=1.25):
    R=np.array(R,dtype=float)
    t=R[:,0]; o=R[:,1]; c=R[:,2]
    N=len(c)
    def roll(x,k):
        M=len(x);out=np.full(M,np.nan);v=np.nan_to_num(x)
        cs=np.cumsum(np.insert(v,0,0.0));c2=np.cumsum(np.insert(v*v,0,0.0))
        m=(cs[k:]-cs[:-k])/k; var=(c2[k:]-c2[:-k])/k-m*m
        out[k-1:]=np.sqrt(np.maximum(var,0.0)*k/(k-1)); return out
    r=np.zeros(N); r[1:]=np.log(np.maximum(c[1:],1e-12)/np.maximum(c[:-1],1e-12))
    s20=roll(r,20)
    idx=np.arange(25,N-W-1)
    fwd=np.array([np.max(np.abs(c[i+1:i+1+W]-c[i]))/c[i] for i in idx])
    pay=np.array([abs(c[min(i+W,N-1)]-o[i+1])/o[i+1] for i in idx])
    sig=s20[idx]; sigT=sig*math.sqrt(W)*IVM
    pr=np.array([prem(x) if np.isfinite(x) and x>0 else np.nan for x in sigT])
    ret=(pay-pr)/pr
    mon=np.array([dt.datetime.utcfromtimestamp(x/1000).month for x in t[idx]])
    names={1:'Jan',2:'Feb',3:'Mar',4:'Apr',5:'May',6:'Jun',7:'Jul'}
    print("=== %s : %d real 2026 daily bars ==="%(label,N))
    print("%-6s %6s %12s %14s %9s"%("month","days","vol persist","straddle ret","WR%"))
    P=[];S=[]
    for m in range(1,8):
        k=mon==m
        if k.sum()<8: continue
        x=sig[k]; y=fwd[k]; rr=ret[k]
        ok=np.isfinite(x)&np.isfinite(y); okr=np.isfinite(rr)
        if ok.sum()<6 or okr.sum()<6: continue
        p=np.corrcoef(x[ok],y[ok])[0,1]
        P.append(p); S.append(rr[okr].mean())
        print("%-6s %6d %+12.4f %+13.2f%% %8.1f%%"%(names[m],k.sum(),p,100*rr[okr].mean(),100*(rr[okr]>0).mean()))
    P=np.array(P);S=np.array(S)
    print("%-6s %6s %+12.4f %+13.2f%%"%("MEAN","",np.nanmean(P),100*np.nanmean(S)))
    print("   positive persistence %d/%d | profitable months %d/%d"%((P>0).sum(),len(P),(S>0).sum(),len(S)))
    print()
    return P,S
run(NEO,"NEO  tNEOF0:USTF0")
run(LTC,"LTC  tLTCF0:USTF0")
